/* KHBD Âm nhạc Lớp 1 KNTT — Bút Xanh, tích hợp NLS + AI */
window.KHO_DATA_L1_AMNHAC = [
{"lop":1,"mon":"Âm nhạc","tuan":1,"tiet":1,"bai":"Chủ đề 1: Âm thanh kì diệu — Học hát: Vào rừng hoa (Việt Anh)","yccd":"1. Năng lực âm nhạc\n- Nhớ tên và hát rõ lời, đúng theo giai điệu bài hát Vào rừng hoa.\n- Bước đầu cảm nhận tính chất vui tươi, trong sáng của bài hát.\n- Biết hát kết hợp vỗ tay theo phách đơn giản.\n2. Năng lực chung\n- Tự chủ và tự học: mạnh dạn hát trước lớp, tự tập lại lời ca.\n- Giao tiếp và hợp tác: biết hát hòa giọng cùng các bạn.\n3. Phẩm chất\n- Yêu thiên nhiên, yêu cảnh đẹp quê hương.","dodung":"- Giáo viên: đàn Organ (hoặc file nhạc đệm), loa, tranh cảnh rừng hoa, thanh phách, thiết bị trình chiếu/loa mở học liệu số.\n- Học sinh: SGK Âm nhạc 1, thanh phách (hoặc nhạc cụ gõ tự tạo).","hoatdong":[{"ten":"1. Khởi động","gv":"- GV cho HS xem tranh cảnh rừng hoa nhiều màu sắc và hỏi: Các em thấy gì trong tranh? Có thích đi chơi trong rừng hoa không?\n- GV bắt nhịp cho cả lớp vận động nhẹ nhàng, dẫn vào bài hát.","hs":"- HS quan sát, trả lời: có hoa, có cây, có bướm...\n- HS vận động, lắng nghe."},{"ten":"2. Khám phá — Nghe và học hát","gv":"- GV mở bản hát mẫu (băng đĩa/học liệu số) cho HS nghe 1-2 lần.\n- GV đọc lời ca theo từng câu, chia bài thành các câu ngắn.\n- GV đàn giai điệu, hát mẫu và bắt nhịp cho HS hát từng câu nối tiếp đến hết bài.","hs":"- HS lắng nghe, nêu cảm nhận ban đầu.\n- HS đọc lời ca theo GV.\n- HS tập hát từng câu, hát nối các câu."},{"ten":"3. Luyện tập","gv":"- GV cho HS hát cả bài theo nhạc đệm, sửa những chỗ hát chưa đúng.\n- GV hướng dẫn hát kết hợp vỗ tay theo phách.","hs":"- HS hát cả bài, hát theo dãy, tổ.\n- HS hát kết hợp vỗ tay theo phách."},{"ten":"4. Vận dụng","gv":"- GV mời vài HS/nhóm hát trước lớp.\n- GV dặn HS về hát cho ông bà, bố mẹ nghe.","hs":"- HS xung phong biểu diễn.\n- HS ghi nhớ nhiệm vụ."},{"ten":"5. Năng lực số & AI (tích hợp)","gv":"- (NLS mức 1 — Khai thác học liệu số) GV cho HS nghe bản hát mẫu chuẩn qua loa/thiết bị số để HS cảm thụ và hát theo.\n- (AI mức 1 — gợi ý) GV có thể dùng ứng dụng nghe nhạc thiếu nhi để bật nhạc đệm; GV thao tác và kiểm soát hoàn toàn.\n⚠ An toàn: HS chỉ nghe và hát theo, không tự thao tác thiết bị; nội dung do GV chọn lọc trước.","hs":"- HS nghe học liệu số, cảm thụ và hát theo.\n- HS quan sát GV sử dụng thiết bị."}]},
{"lop":1,"mon":"Âm nhạc","tuan":2,"tiet":2,"bai":"Chủ đề 1: Âm thanh kì diệu — Ôn bài hát Vào rừng hoa; Đọc nhạc: Đô — Rê — Mi","yccd":"1. Năng lực âm nhạc\n- Hát thuộc, đúng giai điệu bài Vào rừng hoa, kết hợp vỗ tay theo phách.\n- Bước đầu làm quen với ba nốt Đô — Rê — Mi qua kí hiệu bàn tay.\n- Đọc được cao độ ba nốt theo mẫu đơn giản.\n2. Năng lực chung\n- Tự chủ và tự học: tự luyện đọc nốt theo kí hiệu.\n3. Phẩm chất\n- Chăm chỉ luyện tập.","dodung":"- Giáo viên: đàn Organ/file nhạc, loa, tranh kí hiệu bàn tay Đô-Rê-Mi, thanh phách, thiết bị mở học liệu số.\n- Học sinh: SGK Âm nhạc 1, thanh phách.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV cho HS hát lại bài Vào rừng hoa để tạo không khí.","hs":"- HS hát tập thể."},{"ten":"2. Khám phá — Làm quen Đô, Rê, Mi","gv":"- GV giới thiệu ba nốt Đô — Rê — Mi qua kí hiệu bàn tay; đọc mẫu cao độ từng nốt.\n- GV hướng dẫn HS đọc theo, kết hợp làm kí hiệu bàn tay.","hs":"- HS quan sát, nghe và đọc theo cao độ.\n- HS làm kí hiệu bàn tay theo GV."},{"ten":"3. Luyện tập","gv":"- GV cho HS đọc các mẫu âm ngắn với ba nốt; ôn hát bài hát kết hợp vỗ tay theo phách.","hs":"- HS đọc mẫu âm, ôn hát và vỗ tay theo phách."},{"ten":"4. Vận dụng","gv":"- GV cho nhóm/cá nhân đọc lại mẫu âm và làm kí hiệu bàn tay; nhận xét, tuyên dương.","hs":"- HS đọc và làm kí hiệu, nhận xét lẫn nhau."},{"ten":"5. Năng lực số & AI (tích hợp)","gv":"- (NLS mức 1) GV cho HS nghe cao độ mẫu ba nốt Đô-Rê-Mi qua học liệu số/đàn phím ảo để đọc cho đúng.\n⚠ An toàn: HS nghe và đọc theo; GV thao tác và kiểm soát thiết bị.","hs":"- HS nghe cao độ mẫu số, đọc theo cho chuẩn."}]},
{"lop":1,"mon":"Âm nhạc","tuan":3,"tiet":3,"bai":"Chủ đề 1: Âm thanh kì diệu — Thường thức âm nhạc: Âm thanh tự nhiên và âm thanh của nhạc cụ (sáo trúc)","yccd":"1. Năng lực âm nhạc\n- Phân biệt bước đầu âm thanh tự nhiên và âm thanh của nhạc cụ.\n- Nhận biết và gọi tên nhạc cụ sáo trúc; cảm nhận âm sắc của sáo.\n2. Năng lực chung\n- Tự chủ: mạnh dạn nêu cảm nhận về âm thanh.\n3. Phẩm chất\n- Yêu thiên nhiên, yêu âm nhạc.","dodung":"- Giáo viên: loa, file âm thanh tự nhiên (tiếng suối, chim, gió), sáo trúc (hoặc hình ảnh/âm thanh sáo), tranh nhạc cụ, thiết bị số.\n- Học sinh: SGK Âm nhạc 1.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV cho HS chơi trò chơi Lắng nghe và đoán: đoán các âm thanh quen thuộc quanh em.","hs":"- HS lắng nghe, đoán tên âm thanh."},{"ten":"2. Khám phá — Âm thanh tự nhiên và nhạc cụ","gv":"- GV cho HS nghe một số âm thanh tự nhiên và âm thanh của sáo trúc; hỏi HS phân biệt.\n- GV giới thiệu sáo trúc: hình dáng, âm sắc trong trẻo, cách tạo âm.","hs":"- HS nghe, phân biệt âm thanh tự nhiên và nhạc cụ.\n- HS quan sát và nghe giới thiệu về sáo trúc."},{"ten":"3. Luyện tập","gv":"- GV cho HS bắt chước một số âm thanh tự nhiên bằng giọng; nghe lại âm sắc sáo trúc.","hs":"- HS mô phỏng âm thanh, nghe và cảm nhận."},{"ten":"4. Vận dụng","gv":"- GV cho HS kể thêm các âm thanh em nghe được trong cuộc sống và phân loại tự nhiên/nhạc cụ.","hs":"- HS kể và phân loại âm thanh."},{"ten":"5. Năng lực số & AI (tích hợp)","gv":"- (NLS mức 1) GV cho HS nghe âm thanh tự nhiên và âm sắc sáo trúc qua học liệu số để so sánh, phân biệt.\n⚠ An toàn: HS chỉ nghe; GV chọn nguồn học liệu phù hợp lứa tuổi.","hs":"- HS nghe âm thanh số, so sánh và phân biệt."}]},
{"lop":1,"mon":"Âm nhạc","tuan":4,"tiet":4,"bai":"Chủ đề 1: Âm thanh kì diệu — Vận dụng — Sáng tạo: To — nhỏ, dài — ngắn; Ôn tập chủ đề 1","yccd":"1. Năng lực âm nhạc\n- Hát thuộc và biểu diễn được bài Vào rừng hoa kết hợp vận động.\n- Bước đầu nhận biết và mô phỏng âm thanh to — nhỏ, dài — ngắn.\n2. Năng lực chung\n- Giải quyết vấn đề và sáng tạo: tạo động tác, âm thanh mô phỏng.\n3. Phẩm chất\n- Yêu thiên nhiên, tự tin thể hiện.","dodung":"- Giáo viên: đàn/file nhạc, loa, nhạc cụ gõ, thiết bị số.\n- Học sinh: thanh phách, SGK Âm nhạc 1.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV cho HS chơi trò chơi tạo âm thanh to — nhỏ theo hiệu lệnh.","hs":"- HS tham gia trò chơi."},{"ten":"2. Khám phá — To nhỏ, dài ngắn","gv":"- GV hướng dẫn HS phân biệt âm to — nhỏ, dài — ngắn bằng giọng và gõ.\n- Âm to: gõ mạnh; âm nhỏ: gõ nhẹ; âm dài: ngân; âm ngắn: dứt nhanh.","hs":"- HS nghe, phân biệt và thực hiện âm to-nhỏ, dài-ngắn."},{"ten":"3. Luyện tập","gv":"- GV cho HS ôn hát kết hợp vận động, gõ đệm theo tốp ca, cả lớp.","hs":"- HS luyện tập nhiều hình thức."},{"ten":"4. Vận dụng — Sáng tạo","gv":"- GV khuyến khích HS tự nghĩ động tác phụ họa; mời biểu diễn; củng cố nội dung chủ đề.","hs":"- HS sáng tạo động tác, biểu diễn, trả lời củng cố."},{"ten":"5. Năng lực số & AI (tích hợp)","gv":"- (NLS mức 1) GV cho HS nghe âm thanh mẫu to-nhỏ, dài-ngắn từ học liệu số để bắt chước mô phỏng.\n⚠ An toàn: GV chọn nguồn học liệu và kiểm soát thiết bị.","hs":"- HS nghe âm thanh số, mô phỏng sáng tạo."}]},
{"lop":1,"mon":"Âm nhạc","tuan":5,"tiet":5,"bai":"Chủ đề 2: Việt Nam yêu thương — Học hát: Lá cờ Việt Nam (Lý Trọng — Đỗ Mạnh Thường)","yccd":"1. Năng lực âm nhạc\n- Nhớ tên và hát rõ lời, đúng giai điệu bài Lá cờ Việt Nam.\n- Cảm nhận tính chất vui tươi, tự hào của bài hát.\n- Biết hát kết hợp vỗ tay theo phách.\n2. Năng lực chung\n- Giao tiếp và hợp tác: hát hòa giọng cùng bạn.\n3. Phẩm chất\n- Yêu nước: yêu quý lá cờ Tổ quốc, tự hào về đất nước Việt Nam.","dodung":"- Giáo viên: đàn/file nhạc, loa, tranh ảnh lá cờ Việt Nam, thanh phách, thiết bị số.\n- Học sinh: SGK Âm nhạc 1, thanh phách.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV cho HS xem hình ảnh lá cờ đỏ sao vàng và hỏi: Đây là gì? Em thấy lá cờ ở đâu?\n- GV dẫn vào bài hát.","hs":"- HS quan sát, trả lời: lá cờ Việt Nam, thấy ở trường, ngày lễ."},{"ten":"2. Khám phá — Học hát","gv":"- GV mở hát mẫu cho HS nghe 1-2 lần; đọc lời ca theo câu.\n- GV đàn và bắt nhịp cho HS tập hát từng câu nối tiếp đến hết bài.","hs":"- HS nghe mẫu, đọc lời, tập hát từng câu."},{"ten":"3. Luyện tập","gv":"- GV cho HS hát cả bài theo nhạc, sửa sai, kết hợp vỗ tay theo phách.","hs":"- HS hát cả bài, vỗ tay theo phách."},{"ten":"4. Vận dụng","gv":"- GV mời nhóm/cá nhân hát; dặn HS hát cho gia đình nghe.","hs":"- HS biểu diễn, ghi nhớ nhiệm vụ."},{"ten":"5. Năng lực số & AI (tích hợp)","gv":"- (NLS mức 1) GV cho HS nghe bản hát mẫu chuẩn và xem hình ảnh lá cờ, cảnh chào cờ từ học liệu số để tăng cảm xúc.\n⚠ An toàn: HS chỉ nghe/xem; GV chọn học liệu phù hợp.","hs":"- HS nghe/xem học liệu số, cảm thụ và hát theo."}]},
{"lop":1,"mon":"Âm nhạc","tuan":6,"tiet":6,"bai":"Chủ đề 2: Việt Nam yêu thương — Ôn bài hát Lá cờ Việt Nam; Nghe nhạc: Quốc ca Việt Nam (Văn Cao)","yccd":"1. Năng lực âm nhạc\n- Hát thuộc, đúng giai điệu bài Lá cờ Việt Nam, kết hợp vận động phụ họa đơn giản.\n- Lắng nghe và cảm nhận không khí trang nghiêm khi nghe Quốc ca Việt Nam.\n- Biết đứng nghiêm trang khi nghe Quốc ca và khi chào cờ.\n2. Năng lực chung\n- Giao tiếp và hợp tác: phối hợp cùng bạn khi vận động.\n3. Phẩm chất\n- Yêu nước: trân trọng Quốc ca, nghiêm túc khi chào cờ.","dodung":"- Giáo viên: đàn/file nhạc, loa, tranh cảnh lễ chào cờ, thanh phách, thiết bị mở học liệu số.\n- Học sinh: SGK Âm nhạc 1, thanh phách.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV cho HS hát lại bài Lá cờ Việt Nam.","hs":"- HS hát tập thể."},{"ten":"2. Khám phá — Nghe nhạc Quốc ca","gv":"- GV giới thiệu ngắn: Quốc ca là bài Tiến quân ca của nhạc sĩ Văn Cao; khi chào cờ mọi người đứng nghiêm hướng về Quốc kì.\n- GV mở Quốc ca cho HS nghe, hướng dẫn đứng nghiêm trang.","hs":"- HS lắng nghe giới thiệu.\n- HS đứng nghiêm trang nghe Quốc ca."},{"ten":"3. Luyện tập — Ôn bài hát","gv":"- GV cho HS ôn hát Lá cờ Việt Nam, kết hợp vỗ tay theo phách và vận động nhẹ nhàng.","hs":"- HS ôn hát, vận động phụ họa theo GV."},{"ten":"4. Vận dụng","gv":"- GV mời nhóm/cá nhân biểu diễn; dặn HS nghiêm túc khi chào cờ đầu tuần.","hs":"- HS biểu diễn, ghi nhớ lời dặn."},{"ten":"5. Năng lực số & AI (tích hợp)","gv":"- (NLS mức 1) GV cho HS xem đoạn video/hình ảnh số về lễ chào cờ trang nghiêm để cảm nhận.\n- (AI mức 1 — gợi ý) GV có thể dùng thiết bị số phát Quốc ca chuẩn; GV kiểm soát hoàn toàn.\n⚠ An toàn: HS chỉ quan sát và lắng nghe, không tự dùng thiết bị.","hs":"- HS xem, nghe học liệu số và cảm nhận."}]},
{"lop":1,"mon":"Âm nhạc","tuan":7,"tiet":7,"bai":"Chủ đề 2: Việt Nam yêu thương — Nhạc cụ: Thanh phách; Gõ đệm theo bài hát","yccd":"1. Năng lực âm nhạc\n- Nhận biết và gọi đúng tên nhạc cụ thanh phách; biết cách cầm và gõ tạo âm thanh.\n- Biết gõ đệm cho bài hát Lá cờ Việt Nam theo phách.\n2. Năng lực chung\n- Tự chủ và tự học: tự luyện tập gõ đệm.\n- Giao tiếp và hợp tác: phối hợp gõ đệm cùng nhóm.\n3. Phẩm chất\n- Chăm chỉ: kiên trì luyện tập nhạc cụ.","dodung":"- Giáo viên: thanh phách, đàn/file nhạc, loa, tranh nhạc cụ, thiết bị số.\n- Học sinh: thanh phách, SGK Âm nhạc 1.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV cho HS hát lại bài Lá cờ Việt Nam để tạo không khí.","hs":"- HS hát tập thể."},{"ten":"2. Khám phá — Giới thiệu thanh phách","gv":"- GV cho HS xem nhạc cụ thật, giới thiệu hình dáng, âm thanh của thanh phách.\n- GV làm mẫu cách cầm và gõ.","hs":"- HS quan sát, nghe âm thanh, xem cách gõ mẫu."},{"ten":"3. Luyện tập — Gõ đệm","gv":"- GV cho HS thực hành gõ theo phách; gõ đệm cho bài hát, sửa sai.","hs":"- HS thực hành gõ, gõ đệm theo bài hát."},{"ten":"4. Vận dụng","gv":"- GV cho các nhóm luân phiên vừa hát vừa gõ đệm.","hs":"- HS nhóm hát và gõ đệm, nhận xét lẫn nhau."},{"ten":"5. Năng lực số & AI (tích hợp)","gv":"- (NLS mức 1) GV cho HS nghe âm thanh mẫu thanh phách qua học liệu số để phân biệt âm sắc.\n⚠ An toàn: HS nghe và làm theo; GV chọn nguồn học liệu phù hợp lứa tuổi.","hs":"- HS nghe âm thanh nhạc cụ từ thiết bị số, so sánh với gõ thực tế."}]},
{"lop":1,"mon":"Âm nhạc","tuan":8,"tiet":8,"bai":"Chủ đề 2: Việt Nam yêu thương — Vận dụng — Sáng tạo; Ôn tập chủ đề 2","yccd":"1. Năng lực âm nhạc\n- Hát thuộc và biểu diễn được bài Lá cờ Việt Nam kết hợp vận động, gõ đệm.\n- Củng cố kĩ năng gõ thanh phách và cảm nhận tính chất tự hào.\n2. Năng lực chung\n- Giải quyết vấn đề và sáng tạo: nghĩ động tác phụ họa đơn giản.\n3. Phẩm chất\n- Yêu nước, tự tin thể hiện.","dodung":"- Giáo viên: đàn/file nhạc, loa, nhạc cụ gõ, thiết bị số.\n- Học sinh: thanh phách, SGK Âm nhạc 1.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV cho HS chơi Nghe giai điệu đoán tên bài hát đã học.","hs":"- HS lắng nghe, đoán tên bài."},{"ten":"2. Khám phá","gv":"- GV cùng HS nhắc lại nội dung, kĩ năng đã học ở chủ đề 2.","hs":"- HS nhắc lại kiến thức."},{"ten":"3. Luyện tập","gv":"- GV cho HS ôn hát kết hợp vận động, gõ đệm thanh phách theo tốp ca, cả lớp.","hs":"- HS luyện tập nhiều hình thức."},{"ten":"4. Vận dụng — Sáng tạo","gv":"- GV khuyến khích HS sáng tạo động tác phụ họa; mời biểu diễn; củng cố chủ đề.","hs":"- HS sáng tạo, biểu diễn, trả lời củng cố."},{"ten":"5. Năng lực số & AI (tích hợp)","gv":"- (NLS mức 1) GV cho HS nghe lại bản nhạc mẫu từ học liệu số để tự chỉnh sửa khi biểu diễn.\n⚠ An toàn: GV kiểm soát thiết bị và học liệu.","hs":"- HS nghe học liệu số, chỉnh sửa biểu diễn."}]},
{"lop":1,"mon":"Âm nhạc","tuan":9,"tiet":9,"bai":"Ôn tập giữa học kì I — Ôn các bài hát và nội dung chủ đề 1, 2","yccd":"1. Năng lực âm nhạc\n- Hát thuộc, đúng giai điệu các bài Vào rừng hoa, Lá cờ Việt Nam.\n- Củng cố kĩ năng gõ đệm theo phách; đọc ba nốt Đô-Rê-Mi; phân biệt to-nhỏ, dài-ngắn.\n2. Năng lực chung\n- Tự chủ và tự học: tự đánh giá kết quả học tập.\n3. Phẩm chất\n- Chăm chỉ, tự tin biểu diễn.","dodung":"- Giáo viên: đàn/file nhạc, loa, nhạc cụ gõ, thiết bị số.\n- Học sinh: thanh phách, SGK Âm nhạc 1.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV cho HS chơi Nghe giai điệu đoán tên bài hát đã học.","hs":"- HS lắng nghe, đoán tên bài."},{"ten":"2. Khám phá — Hệ thống lại","gv":"- GV cùng HS nhắc lại tên các bài hát, nội dung đã học ở chủ đề 1, 2.","hs":"- HS nhắc lại kiến thức."},{"ten":"3. Luyện tập","gv":"- GV cho HS ôn lần lượt từng bài hát kết hợp gõ đệm, vận động; ôn đọc nốt Đô-Rê-Mi.","hs":"- HS ôn hát, gõ đệm và đọc nốt."},{"ten":"4. Vận dụng","gv":"- GV tổ chức cho các nhóm biểu diễn, nhận xét, tuyên dương.","hs":"- HS biểu diễn, nhận xét lẫn nhau."},{"ten":"5. Năng lực số & AI (tích hợp)","gv":"- (NLS mức 1) GV cho HS nghe lại các bản nhạc mẫu từ học liệu số để so sánh và tự chỉnh sửa.\n- (AI mức 1 — gợi ý) GV có thể dùng app hát karaoke thiếu nhi (hiển thị lời) để HS ôn hát; GV thao tác và kiểm soát.\n⚠ An toàn: HS chỉ hát theo, không tự nhập liệu; nội dung do GV chọn.","hs":"- HS nghe/hát theo học liệu số, tự chỉnh sửa."}]},
{"lop":1,"mon":"Âm nhạc","tuan":10,"tiet":10,"bai":"Chủ đề 3: Mái trường thân yêu — Học hát: Lớp Một thân yêu (Bùi Anh Tôn)","yccd":"1. Năng lực âm nhạc\n- Nhớ tên và hát rõ lời, đúng giai điệu bài Lớp Một thân yêu.\n- Cảm nhận tính chất vui tươi, hồn nhiên của bài hát về mái trường.\n2. Năng lực chung\n- Giao tiếp và hợp tác: hát hòa giọng cùng bạn.\n3. Phẩm chất\n- Yêu trường lớp, yêu quý thầy cô và bạn bè.","dodung":"- Giáo viên: đàn/file nhạc, loa, tranh cảnh trường lớp, thanh phách, thiết bị số.\n- Học sinh: SGK Âm nhạc 1, thanh phách.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV cho HS xem tranh cảnh lớp học, hỏi các em thích gì ở lớp mình, dẫn vào bài.","hs":"- HS quan sát, trả lời."},{"ten":"2. Khám phá — Học hát","gv":"- GV mở hát mẫu, đọc lời ca theo câu.\n- GV đàn và bắt nhịp cho HS tập hát từng câu đến hết bài.","hs":"- HS nghe mẫu, đọc lời, tập hát từng câu."},{"ten":"3. Luyện tập","gv":"- GV cho HS hát cả bài, sửa sai, kết hợp vỗ tay theo phách.","hs":"- HS hát cả bài, vỗ tay theo phách."},{"ten":"4. Vận dụng","gv":"- GV mời nhóm/cá nhân hát; dặn HS hát cho gia đình nghe.","hs":"- HS biểu diễn, ghi nhớ nhiệm vụ."},{"ten":"5. Năng lực số & AI (tích hợp)","gv":"- (NLS mức 1) GV cho HS nghe bản hát mẫu chuẩn từ học liệu số để cảm thụ và hát theo.\n⚠ An toàn: HS chỉ nghe và hát theo; GV chọn học liệu phù hợp.","hs":"- HS nghe học liệu số, cảm thụ và hát theo."}]},
{"lop":1,"mon":"Âm nhạc","tuan":11,"tiet":11,"bai":"Chủ đề 3: Mái trường thân yêu — Ôn bài hát Lớp Một thân yêu; Nghe nhạc: Những bông hoa những bài ca (Hoàng Long)","yccd":"1. Năng lực âm nhạc\n- Hát thuộc, đúng giai điệu, kết hợp vận động phụ họa.\n- Lắng nghe và cảm nhận giai điệu vui tươi của bài Những bông hoa những bài ca; biết vận động theo nhạc.\n2. Năng lực chung\n- Tự chủ: mạnh dạn nêu cảm nhận.\n3. Phẩm chất\n- Yêu trường lớp, biết ơn thầy cô.","dodung":"- Giáo viên: đàn/file nhạc, loa, tranh minh họa, thanh phách, thiết bị số.\n- Học sinh: thanh phách, SGK Âm nhạc 1.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV cho HS hát lại bài Lớp Một thân yêu.","hs":"- HS hát tập thể."},{"ten":"2. Khám phá — Nghe nhạc","gv":"- GV mở bài Những bông hoa những bài ca cho HS nghe; hỏi cảm nhận: vui hay buồn, nhanh hay chậm.","hs":"- HS lắng nghe, nêu cảm nhận."},{"ten":"3. Luyện tập","gv":"- GV cho HS ôn hát kết hợp vận động; nghe lại bài nghe nhạc và vận động nhẹ nhàng theo.","hs":"- HS ôn hát, vận động theo nhạc."},{"ten":"4. Vận dụng","gv":"- GV mời nhóm biểu diễn, nhận xét, tuyên dương.","hs":"- HS biểu diễn, nhận xét."},{"ten":"5. Năng lực số & AI (tích hợp)","gv":"- (NLS mức 1) GV cho HS xem video/hình ảnh số về hoạt động trường lớp kết hợp nghe nhạc để cảm thụ.\n⚠ An toàn: HS chỉ xem/nghe; GV chọn nội dung phù hợp.","hs":"- HS xem/nghe học liệu số, nêu cảm nhận."}]},
{"lop":1,"mon":"Âm nhạc","tuan":12,"tiet":12,"bai":"Chủ đề 3: Mái trường thân yêu — Đọc nhạc: Ban nhạc Đô — Rê — Mi","yccd":"1. Năng lực âm nhạc\n- Đọc đúng cao độ ba nốt Đô — Rê — Mi theo kí hiệu bàn tay.\n- Đọc được bài Ban nhạc Đô — Rê — Mi kết hợp gõ đệm đơn giản.\n2. Năng lực chung\n- Tự chủ và tự học: tự luyện đọc nốt.\n3. Phẩm chất\n- Chăm chỉ luyện tập.","dodung":"- Giáo viên: đàn/file nhạc, loa, tranh kí hiệu bàn tay, bảng phụ bài đọc nhạc, thiết bị số.\n- Học sinh: thanh phách, SGK Âm nhạc 1.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV cho HS ôn lại cao độ ba nốt Đô-Rê-Mi qua kí hiệu bàn tay.","hs":"- HS đọc và làm kí hiệu bàn tay."},{"ten":"2. Khám phá — Ban nhạc Đô-Rê-Mi","gv":"- GV giới thiệu bài đọc nhạc; đọc mẫu từng câu kết hợp kí hiệu bàn tay.","hs":"- HS nghe mẫu, đọc theo từng câu."},{"ten":"3. Luyện tập","gv":"- GV cho HS đọc cả bài kết hợp làm kí hiệu bàn tay và gõ đệm; sửa sai.","hs":"- HS đọc bài, làm kí hiệu và gõ đệm."},{"ten":"4. Vận dụng","gv":"- GV cho nhóm/cá nhân đọc lại và làm kí hiệu; nhận xét, tuyên dương.","hs":"- HS đọc, làm kí hiệu, nhận xét lẫn nhau."},{"ten":"5. Năng lực số & AI (tích hợp)","gv":"- (NLS mức 1) GV cho HS nghe cao độ mẫu bài đọc nhạc qua học liệu số/đàn phím ảo để đọc cho đúng.\n⚠ An toàn: HS nghe và đọc theo; GV thao tác và kiểm soát thiết bị.","hs":"- HS nghe cao độ mẫu số, đọc theo cho chuẩn."}]},
{"lop":1,"mon":"Âm nhạc","tuan":13,"tiet":13,"bai":"Chủ đề 3: Mái trường thân yêu — Vận dụng — Sáng tạo: To — nhỏ, cao — thấp; Ôn tập chủ đề 3","yccd":"1. Năng lực âm nhạc\n- Hát thuộc và biểu diễn bài Lớp Một thân yêu kết hợp vận động.\n- Bước đầu nhận biết âm to — nhỏ, cao — thấp và vận động theo.\n2. Năng lực chung\n- Giải quyết vấn đề và sáng tạo: nghĩ động tác phụ họa.\n3. Phẩm chất\n- Yêu trường lớp, tự tin thể hiện.","dodung":"- Giáo viên: đàn/file nhạc, loa, nhạc cụ gõ, thiết bị số.\n- Học sinh: thanh phách, SGK Âm nhạc 1.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV cho HS chơi trò chơi vận động theo âm cao — thấp, to — nhỏ.","hs":"- HS tham gia trò chơi."},{"ten":"2. Khám phá — To nhỏ, cao thấp","gv":"- GV đàn/mở âm to — nhỏ, cao — thấp; hướng dẫn HS nhận biết và vận động.","hs":"- HS nghe, phân biệt và vận động theo."},{"ten":"3. Luyện tập","gv":"- GV cho HS ôn hát kết hợp vận động, gõ đệm theo tốp ca, cả lớp.","hs":"- HS luyện tập nhiều hình thức."},{"ten":"4. Vận dụng — Sáng tạo","gv":"- GV khuyến khích HS sáng tạo động tác; mời biểu diễn; củng cố chủ đề.","hs":"- HS sáng tạo, biểu diễn, trả lời củng cố."},{"ten":"5. Năng lực số & AI (tích hợp)","gv":"- (NLS mức 1) GV cho HS nghe lại bản nhạc mẫu từ học liệu số để tự chỉnh sửa khi biểu diễn.\n⚠ An toàn: GV kiểm soát thiết bị và học liệu.","hs":"- HS nghe học liệu số, chỉnh sửa biểu diễn."}]},
{"lop":1,"mon":"Âm nhạc","tuan":14,"tiet":14,"bai":"Chủ đề 4: Vòng tay bạn bè — Học hát: Chào người bạn mới đến (Lương Bằng Vinh)","yccd":"1. Năng lực âm nhạc\n- Nhớ tên và hát rõ lời, đúng giai điệu bài Chào người bạn mới đến.\n- Cảm nhận tính chất vui tươi, thân thiện của bài hát.\n2. Năng lực chung\n- Giao tiếp và hợp tác: hát hòa giọng cùng bạn.\n3. Phẩm chất\n- Nhân ái: yêu quý bạn bè, đoàn kết.","dodung":"- Giáo viên: đàn/file nhạc, loa, tranh tình bạn, thanh phách, thiết bị số.\n- Học sinh: SGK Âm nhạc 1, thanh phách.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV cho HS chơi trò chơi kết bạn, dẫn vào bài hát.","hs":"- HS tham gia trò chơi."},{"ten":"2. Khám phá — Học hát","gv":"- GV mở hát mẫu, đọc lời ca theo câu.\n- GV đàn và bắt nhịp cho HS tập hát từng câu đến hết bài.","hs":"- HS nghe mẫu, đọc lời, tập hát từng câu."},{"ten":"3. Luyện tập","gv":"- GV cho HS hát cả bài, sửa sai, kết hợp vỗ tay theo nhịp.","hs":"- HS hát cả bài, vỗ tay theo nhịp."},{"ten":"4. Vận dụng","gv":"- GV mời nhóm/cặp bạn hát; dặn HS hát cho bạn bè, gia đình nghe.","hs":"- HS biểu diễn, ghi nhớ nhiệm vụ."},{"ten":"5. Năng lực số & AI (tích hợp)","gv":"- (NLS mức 1) GV cho HS nghe bản hát mẫu chuẩn từ học liệu số để cảm thụ và hát theo.\n⚠ An toàn: HS chỉ nghe và hát theo; GV chọn học liệu phù hợp.","hs":"- HS nghe học liệu số, cảm thụ và hát theo."}]},
{"lop":1,"mon":"Âm nhạc","tuan":15,"tiet":15,"bai":"Chủ đề 4: Vòng tay bạn bè — Ôn bài hát Chào người bạn mới đến; Nhạc cụ: Trống con","yccd":"1. Năng lực âm nhạc\n- Hát thuộc, đúng giai điệu, kết hợp vận động phụ họa theo cặp/nhóm.\n- Nhận biết, gọi tên nhạc cụ trống con; biết cách gõ tạo âm thanh và gõ đệm theo bài hát.\n2. Năng lực chung\n- Giao tiếp và hợp tác: phối hợp biểu diễn, gõ đệm cùng bạn.\n3. Phẩm chất\n- Nhân ái, đoàn kết, chăm chỉ luyện tập.","dodung":"- Giáo viên: trống con (hoặc thay thế), đàn/file nhạc, loa, tranh nhạc cụ, thiết bị số.\n- Học sinh: thanh phách, SGK Âm nhạc 1.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV cho HS hát lại bài Chào người bạn mới đến.","hs":"- HS hát tập thể."},{"ten":"2. Khám phá — Giới thiệu trống con","gv":"- GV cho HS xem trống con, giới thiệu hình dáng, âm thanh; làm mẫu cách gõ.","hs":"- HS quan sát, nghe âm thanh, xem mẫu."},{"ten":"3. Luyện tập — Gõ đệm","gv":"- GV cho HS thực hành gõ trống con theo phách; gõ đệm cho bài hát; sửa sai.","hs":"- HS thực hành gõ và gõ đệm theo bài hát."},{"ten":"4. Vận dụng","gv":"- GV cho nhóm luân phiên hát và gõ đệm trống con.","hs":"- HS nhóm hát và gõ đệm, nhận xét lẫn nhau."},{"ten":"5. Năng lực số & AI (tích hợp)","gv":"- (NLS mức 1) GV cho HS nghe âm thanh mẫu trống con qua học liệu số để phân biệt âm sắc.\n⚠ An toàn: HS nghe và làm theo; GV chọn nguồn học liệu.","hs":"- HS nghe âm thanh số, so sánh với gõ thực tế."}]},
{"lop":1,"mon":"Âm nhạc","tuan":16,"tiet":16,"bai":"Chủ đề 4: Vòng tay bạn bè — Thường thức âm nhạc: Trống cái; Nghe nhạc: Vũ khúc thiên nga (Trai-cốp-xki)","yccd":"1. Năng lực âm nhạc\n- Nhận biết nhạc cụ trống cái; cảm nhận âm thanh vang, trầm của trống cái.\n- Lắng nghe và cảm nhận giai điệu nhẹ nhàng, uyển chuyển của Vũ khúc thiên nga; biết vận động theo nhạc.\n2. Năng lực chung\n- Tự chủ: mạnh dạn nêu cảm nhận.\n3. Phẩm chất\n- Yêu âm nhạc, yêu cái đẹp.","dodung":"- Giáo viên: loa, file nhạc, hình ảnh/video trống cái và múa thiên nga, thiết bị mở học liệu số.\n- Học sinh: SGK Âm nhạc 1.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV cho HS nghe âm thanh một tiếng trống cái, hỏi cảm nhận âm thanh to hay nhỏ, vang hay không.","hs":"- HS nghe, nêu cảm nhận."},{"ten":"2. Khám phá — Trống cái và nghe nhạc","gv":"- GV giới thiệu trống cái: hình dáng lớn, âm thanh vang, trầm.\n- GV mở trích đoạn Vũ khúc thiên nga cho HS nghe; hỏi cảm nhận: nhẹ nhàng hay mạnh mẽ.","hs":"- HS nghe giới thiệu trống cái; lắng nghe bài nghe nhạc và nêu cảm nhận."},{"ten":"3. Luyện tập — Vận động theo nhạc","gv":"- GV hướng dẫn HS vận động cơ thể nhẹ nhàng theo giai điệu (dang tay như cánh thiên nga).","hs":"- HS vận động theo nhạc."},{"ten":"4. Vận dụng","gv":"- GV cho HS nghe lại và mời vài HS biểu diễn động tác tự nghĩ.","hs":"- HS biểu diễn động tác sáng tạo."},{"ten":"5. Năng lực số & AI (tích hợp)","gv":"- (NLS mức 1) GV cho HS xem video/hình ảnh số về múa thiên nga (ba-lê) kết hợp nghe nhạc để cảm thụ trọn vẹn.\n⚠ An toàn: HS chỉ xem/nghe; GV chọn nội dung phù hợp lứa tuổi.","hs":"- HS xem, nghe học liệu số, nêu cảm nhận."}]},
{"lop":1,"mon":"Âm nhạc","tuan":17,"tiet":17,"bai":"Chủ đề 4: Vòng tay bạn bè — Vận dụng — Sáng tạo; Ôn tập chủ đề 4","yccd":"1. Năng lực âm nhạc\n- Hát thuộc và biểu diễn bài Chào người bạn mới đến kết hợp vận động, gõ đệm.\n- Củng cố kĩ năng gõ trống con và cảm nhận âm sắc nhạc cụ.\n2. Năng lực chung\n- Giải quyết vấn đề và sáng tạo: nghĩ động tác, cách gõ mới.\n3. Phẩm chất\n- Nhân ái, đoàn kết, tự tin thể hiện.","dodung":"- Giáo viên: đàn/file nhạc, loa, nhạc cụ gõ, thiết bị số.\n- Học sinh: thanh phách, SGK Âm nhạc 1.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV cho HS chơi trò chơi gõ tiết tấu đối đáp theo nhóm.","hs":"- HS tham gia trò chơi."},{"ten":"2. Khám phá","gv":"- GV cùng HS nhắc lại nội dung, kĩ năng đã học ở chủ đề 4.","hs":"- HS nhắc lại kiến thức."},{"ten":"3. Luyện tập","gv":"- GV cho HS ôn hát kết hợp vận động, gõ đệm theo cặp/nhóm, cả lớp.","hs":"- HS luyện tập nhiều hình thức."},{"ten":"4. Vận dụng — Sáng tạo","gv":"- GV khuyến khích HS sáng tạo động tác, cách gõ; mời biểu diễn; củng cố chủ đề.","hs":"- HS sáng tạo, biểu diễn, trả lời củng cố."},{"ten":"5. Năng lực số & AI (tích hợp)","gv":"- (NLS mức 1) GV cho HS nghe lại bản nhạc mẫu từ học liệu số để tự chỉnh sửa khi biểu diễn.\n⚠ An toàn: GV kiểm soát thiết bị và học liệu.","hs":"- HS nghe học liệu số, chỉnh sửa biểu diễn."}]},
{"lop":1,"mon":"Âm nhạc","tuan":18,"tiet":18,"bai":"Ôn tập và đánh giá cuối học kì I","yccd":"1. Năng lực âm nhạc\n- Hát thuộc, đúng giai điệu các bài hát đã học trong học kì I; biết gõ đệm và vận động phù hợp.\n- Nhận biết một số nhạc cụ gõ (thanh phách, trống con) và ba nốt Đô-Rê-Mi.\n2. Năng lực chung\n- Tự chủ và tự học: tự đánh giá kết quả học tập của bản thân.\n3. Phẩm chất\n- Chăm chỉ, tự tin biểu diễn.","dodung":"- Giáo viên: đàn/file nhạc, loa, nhạc cụ gõ, phiếu đánh giá, thiết bị số.\n- Học sinh: thanh phách, SGK Âm nhạc 1.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV cho HS chơi Nghe giai điệu đoán tên bài hát đã học trong học kì.","hs":"- HS lắng nghe, đoán tên bài."},{"ten":"2. Khám phá — Hệ thống","gv":"- GV cùng HS hệ thống lại các bài hát, nhạc cụ, nội dung đã học học kì I.","hs":"- HS nhắc lại kiến thức."},{"ten":"3. Luyện tập — Đánh giá","gv":"- GV cho từng nhóm/cá nhân biểu diễn một bài tự chọn; GV nhận xét, đánh giá theo sự tiến bộ.","hs":"- HS biểu diễn, tự nhận xét và nhận xét bạn."},{"ten":"4. Vận dụng","gv":"- GV tuyên dương, động viên HS; dặn dò chuẩn bị học kì II.","hs":"- HS lắng nghe, ghi nhớ."},{"ten":"5. Năng lực số & AI (tích hợp)","gv":"- (NLS mức 1) GV cho HS nghe lại các bản nhạc mẫu từ học liệu số để ôn tập và tự đánh giá.\n⚠ An toàn: GV thao tác thiết bị, HS chỉ nghe và hát theo.","hs":"- HS nghe học liệu số, tự ôn và đánh giá."}]},
{"lop":1,"mon":"Âm nhạc","tuan":19,"tiet":19,"bai":"Chủ đề 5: Nhịp điệu mùa xuân — Học hát: Xúc xắc xúc xẻ (Dân gian Việt Nam)","yccd":"1. Năng lực âm nhạc\n- Nhớ tên và hát rõ lời, đúng giai điệu bài Xúc xắc xúc xẻ.\n- Cảm nhận không khí vui tươi, rộn ràng của mùa xuân qua bài hát.\n- Biết hát kết hợp vận động cơ thể theo nhịp.\n2. Năng lực chung\n- Giao tiếp và hợp tác: hát hòa giọng cùng bạn.\n3. Phẩm chất\n- Yêu truyền thống, yêu không khí mùa xuân.","dodung":"- Giáo viên: đàn/file nhạc, loa, tranh cảnh mùa xuân/ngày Tết, thanh phách, thiết bị số.\n- Học sinh: SGK Âm nhạc 1, thanh phách.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV hỏi HS về mùa xuân, ngày Tết (hoa gì nở, có gì vui), dẫn vào bài.","hs":"- HS trả lời, chia sẻ."},{"ten":"2. Khám phá — Học hát","gv":"- GV mở hát mẫu, đọc lời ca theo câu.\n- GV đàn và bắt nhịp cho HS tập hát từng câu đến hết bài.","hs":"- HS nghe mẫu, đọc lời, tập hát từng câu."},{"ten":"3. Luyện tập","gv":"- GV cho HS hát cả bài, sửa sai, kết hợp vỗ tay và vận động cơ thể theo nhịp.","hs":"- HS hát cả bài, vỗ tay và vận động theo nhịp."},{"ten":"4. Vận dụng","gv":"- GV mời nhóm/cá nhân hát; dặn HS hát cho gia đình nghe dịp xuân.","hs":"- HS biểu diễn, ghi nhớ nhiệm vụ."},{"ten":"5. Năng lực số & AI (tích hợp)","gv":"- (NLS mức 1) GV cho HS nghe bản hát mẫu và xem hình ảnh không khí mùa xuân từ học liệu số.\n⚠ An toàn: HS chỉ nghe/xem; GV chọn học liệu phù hợp.","hs":"- HS nghe/xem học liệu số, cảm thụ và hát theo."}]},
{"lop":1,"mon":"Âm nhạc","tuan":20,"tiet":20,"bai":"Chủ đề 5: Nhịp điệu mùa xuân — Ôn bài hát Xúc xắc xúc xẻ; Vận động theo nhịp điệu","yccd":"1. Năng lực âm nhạc\n- Hát thuộc, đúng giai điệu Xúc xắc xúc xẻ, kết hợp vận động cơ thể theo nhịp điệu bài hát.\n- Biết hát theo hình thức tốp ca, song ca, cá nhân.\n2. Năng lực chung\n- Giao tiếp và hợp tác: phối hợp biểu diễn.\n3. Phẩm chất\n- Chăm chỉ, tự tin, yêu mùa xuân.","dodung":"- Giáo viên: đàn/file nhạc, loa, thanh phách, thiết bị số.\n- Học sinh: thanh phách, SGK Âm nhạc 1.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV cho HS hát lại bài Xúc xắc xúc xẻ.","hs":"- HS hát tập thể."},{"ten":"2. Khám phá — Vận động theo nhịp","gv":"- GV làm mẫu vài động tác vận động cơ thể theo nhịp điệu bài hát; hướng dẫn HS.","hs":"- HS quan sát, làm theo."},{"ten":"3. Luyện tập","gv":"- GV cho HS ôn hát kết hợp vận động theo dãy/tổ; hát tốp ca, song ca.","hs":"- HS ôn hát và vận động theo nhiều hình thức."},{"ten":"4. Vận dụng","gv":"- GV cho nhóm luân phiên biểu diễn, nhận xét, tuyên dương.","hs":"- HS biểu diễn, nhận xét."},{"ten":"5. Năng lực số & AI (tích hợp)","gv":"- (NLS mức 1) GV mở nhạc đệm chuẩn từ thiết bị số để HS hát giữ nhịp ổn định khi vận động.\n⚠ An toàn: GV thao tác và kiểm soát thiết bị.","hs":"- HS hát và vận động theo nhạc đệm số."}]},
{"lop":1,"mon":"Âm nhạc","tuan":21,"tiet":21,"bai":"Chủ đề 5: Nhịp điệu mùa xuân — Đọc nhạc: Những người bạn của Đô — Rê — Mi","yccd":"1. Năng lực âm nhạc\n- Nhận biết và ghi nhớ thêm hai nốt Pha, Son (bên cạnh Đô, Rê, Mi).\n- Đọc được bài Những người bạn của Đô — Rê — Mi theo kí hiệu bàn tay.\n2. Năng lực chung\n- Tự chủ và tự học: tự luyện đọc nốt.\n3. Phẩm chất\n- Chăm chỉ luyện tập.","dodung":"- Giáo viên: đàn/file nhạc, loa, tranh kí hiệu bàn tay 5 nốt, bảng phụ bài đọc nhạc, thiết bị số.\n- Học sinh: thanh phách, SGK Âm nhạc 1.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV cho HS ôn lại cao độ Đô-Rê-Mi qua kí hiệu bàn tay.","hs":"- HS đọc và làm kí hiệu bàn tay."},{"ten":"2. Khám phá — Làm quen Pha, Son","gv":"- GV giới thiệu thêm hai nốt Pha, Son; đọc mẫu cao độ và kí hiệu bàn tay.","hs":"- HS nghe, đọc theo và làm kí hiệu."},{"ten":"3. Luyện tập","gv":"- GV cho HS đọc bài Những người bạn của Đô-Rê-Mi kết hợp kí hiệu bàn tay; sửa sai.","hs":"- HS đọc bài, làm kí hiệu bàn tay."},{"ten":"4. Vận dụng","gv":"- GV cho nhóm/cá nhân đọc lại và làm kí hiệu; nhận xét, tuyên dương.","hs":"- HS đọc, làm kí hiệu, nhận xét lẫn nhau."},{"ten":"5. Năng lực số & AI (tích hợp)","gv":"- (NLS mức 1) GV cho HS nghe cao độ mẫu 5 nốt qua học liệu số/đàn phím ảo để đọc cho đúng.\n⚠ An toàn: HS nghe và đọc theo; GV thao tác và kiểm soát thiết bị.","hs":"- HS nghe cao độ mẫu số, đọc theo cho chuẩn."}]},
{"lop":1,"mon":"Âm nhạc","tuan":22,"tiet":22,"bai":"Chủ đề 5: Nhịp điệu mùa xuân — Vận dụng — Sáng tạo; Ôn tập chủ đề 5","yccd":"1. Năng lực âm nhạc\n- Hát thuộc và biểu diễn bài Xúc xắc xúc xẻ kết hợp vận động, gõ đệm.\n- Củng cố đọc nhạc 5 nốt và cảm nhận nhịp điệu mùa xuân.\n2. Năng lực chung\n- Giải quyết vấn đề và sáng tạo: nghĩ động tác phụ họa.\n3. Phẩm chất\n- Yêu mùa xuân, tự tin thể hiện.","dodung":"- Giáo viên: đàn/file nhạc, loa, nhạc cụ gõ, thiết bị số.\n- Học sinh: thanh phách, SGK Âm nhạc 1.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV cho HS chơi trò chơi vận động theo nhạc mùa xuân.","hs":"- HS tham gia trò chơi."},{"ten":"2. Khám phá","gv":"- GV cùng HS nhắc lại nội dung, kĩ năng đã học ở chủ đề 5.","hs":"- HS nhắc lại kiến thức."},{"ten":"3. Luyện tập","gv":"- GV cho HS ôn hát kết hợp vận động, gõ đệm; ôn đọc nhạc theo tốp ca, cả lớp.","hs":"- HS luyện tập nhiều hình thức."},{"ten":"4. Vận dụng — Sáng tạo","gv":"- GV khuyến khích HS sáng tạo động tác; mời biểu diễn; củng cố chủ đề.","hs":"- HS sáng tạo, biểu diễn, trả lời củng cố."},{"ten":"5. Năng lực số & AI (tích hợp)","gv":"- (NLS mức 1) GV cho HS nghe lại bản nhạc mẫu từ học liệu số để tự chỉnh sửa khi biểu diễn.\n⚠ An toàn: GV kiểm soát thiết bị và học liệu.","hs":"- HS nghe học liệu số, chỉnh sửa biểu diễn."}]},
{"lop":1,"mon":"Âm nhạc","tuan":23,"tiet":23,"bai":"Chủ đề 6: Về miền dân ca — Học hát: Gà gáy (Dân ca Cống Khao, lời mới: Huy Trân)","yccd":"1. Năng lực âm nhạc\n- Nhớ tên và hát rõ lời, đúng giai điệu bài Gà gáy.\n- Bước đầu cảm nhận nét mộc mạc, vui tươi của làn điệu dân ca.\n2. Năng lực chung\n- Giao tiếp và hợp tác: hát hòa giọng cùng bạn.\n3. Phẩm chất\n- Yêu quê hương, trân trọng làn điệu dân ca của các dân tộc; yêu lao động.","dodung":"- Giáo viên: đàn/file nhạc, loa, tranh cảnh làng quê/gà gáy sáng, thanh phách, thiết bị số.\n- Học sinh: SGK Âm nhạc 1, thanh phách.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV cho HS bắt chước tiếng gà gáy, giới thiệu ngắn về dân ca, dẫn vào bài Gà gáy.","hs":"- HS bắt chước tiếng gà, lắng nghe."},{"ten":"2. Khám phá — Học hát","gv":"- GV mở hát mẫu, đọc lời ca theo câu.\n- GV đàn và bắt nhịp cho HS tập hát từng câu đến hết bài.","hs":"- HS nghe mẫu, đọc lời, tập hát từng câu."},{"ten":"3. Luyện tập","gv":"- GV cho HS hát cả bài, sửa sai, kết hợp vỗ tay theo phách.","hs":"- HS hát cả bài, vỗ tay theo phách."},{"ten":"4. Vận dụng","gv":"- GV mời nhóm/cá nhân hát; dặn HS hát cho gia đình nghe.","hs":"- HS biểu diễn, ghi nhớ nhiệm vụ."},{"ten":"5. Năng lực số & AI (tích hợp)","gv":"- (NLS mức 1) GV cho HS nghe bản hát mẫu dân ca chuẩn từ học liệu số để cảm thụ nét đặc trưng.\n⚠ An toàn: HS chỉ nghe; GV chọn học liệu phù hợp.","hs":"- HS nghe học liệu số, cảm thụ và hát theo."}]},
{"lop":1,"mon":"Âm nhạc","tuan":24,"tiet":24,"bai":"Chủ đề 6: Về miền dân ca — Ôn bài hát Gà gáy; Nghe nhạc: một làn điệu dân ca (Lí cây bông)","yccd":"1. Năng lực âm nhạc\n- Hát thuộc, đúng giai điệu Gà gáy, kết hợp vỗ tay theo phách và vận động.\n- Lắng nghe và cảm nhận nét duyên dáng của một làn điệu dân ca; biết vận động nhẹ nhàng theo.\n2. Năng lực chung\n- Tự chủ: mạnh dạn nêu cảm nhận.\n3. Phẩm chất\n- Yêu dân ca, yêu quê hương.","dodung":"- Giáo viên: đàn/file nhạc, loa, tranh minh họa dân ca, thanh phách, thiết bị số.\n- Học sinh: thanh phách, SGK Âm nhạc 1.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV cho HS hát lại bài Gà gáy.","hs":"- HS hát tập thể."},{"ten":"2. Khám phá — Nghe nhạc dân ca","gv":"- GV mở một làn điệu dân ca cho HS nghe; hỏi cảm nhận: vui hay êm dịu, nhanh hay chậm.","hs":"- HS lắng nghe, nêu cảm nhận."},{"ten":"3. Luyện tập","gv":"- GV cho HS ôn hát Gà gáy kết hợp vỗ tay theo phách; nghe lại làn điệu và vận động nhẹ nhàng.","hs":"- HS ôn hát, vận động theo nhạc."},{"ten":"4. Vận dụng","gv":"- GV mời nhóm biểu diễn, nhận xét, tuyên dương.","hs":"- HS biểu diễn, nhận xét."},{"ten":"5. Năng lực số & AI (tích hợp)","gv":"- (NLS mức 1) GV cho HS xem video/hình ảnh số minh họa làn điệu dân ca kết hợp nghe nhạc để cảm thụ.\n⚠ An toàn: HS chỉ xem/nghe; GV chọn nội dung phù hợp.","hs":"- HS xem/nghe học liệu số, nêu cảm nhận."}]},
{"lop":1,"mon":"Âm nhạc","tuan":25,"tiet":25,"bai":"Chủ đề 6: Về miền dân ca — Nhạc cụ: Ôn gõ đệm; Trò chơi tiết tấu dân gian","yccd":"1. Năng lực âm nhạc\n- Gõ đệm cho bài Gà gáy bằng nhạc cụ gõ theo phách, theo tiết tấu.\n- Tham gia trò chơi gõ tiết tấu đối đáp theo nhóm.\n2. Năng lực chung\n- Giao tiếp và hợp tác: phối hợp nhóm khi chơi tiết tấu.\n3. Phẩm chất\n- Chăm chỉ luyện tập, đoàn kết.","dodung":"- Giáo viên: nhạc cụ gõ (thanh phách, trống con, song loan), đàn/file nhạc, loa, thiết bị số.\n- Học sinh: thanh phách, SGK Âm nhạc 1.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV cho HS chơi Nghe tiết tấu đoán tên bài hát.","hs":"- HS lắng nghe, đoán."},{"ten":"2. Khám phá — Ôn nhạc cụ gõ","gv":"- GV cho HS nhắc lại tên và cách gõ các nhạc cụ đã học; gõ mẫu tiết tấu.","hs":"- HS nhắc lại, quan sát mẫu."},{"ten":"3. Luyện tập — Gõ đệm","gv":"- GV cho HS gõ đệm cho bài Gà gáy theo phách và tiết tấu; sửa sai.","hs":"- HS gõ đệm theo bài hát."},{"ten":"4. Vận dụng — Trò chơi tiết tấu","gv":"- GV chia lớp 2 nhóm chơi gõ tiết tấu đối đáp; tuyên dương nhóm gõ tốt.","hs":"- HS chơi gõ tiết tấu theo nhóm."},{"ten":"5. Năng lực số & AI (tích hợp)","gv":"- (NLS mức 1) GV cho HS nghe mẫu tiết tấu chuẩn qua học liệu số để gõ theo cho đúng.\n⚠ An toàn: HS nghe và gõ theo; GV chọn nguồn học liệu.","hs":"- HS nghe mẫu số, gõ theo tiết tấu."}]},
{"lop":1,"mon":"Âm nhạc","tuan":26,"tiet":26,"bai":"Chủ đề 6: Về miền dân ca — Vận dụng — Sáng tạo; Ôn tập chủ đề 6","yccd":"1. Năng lực âm nhạc\n- Hát thuộc và biểu diễn bài Gà gáy kết hợp vận động, gõ đệm.\n- Bước đầu sáng tạo động tác phụ họa mang màu sắc dân gian.\n2. Năng lực chung\n- Giải quyết vấn đề và sáng tạo: nghĩ động tác, cách gõ mới.\n3. Phẩm chất\n- Yêu dân ca, tự tin thể hiện.","dodung":"- Giáo viên: đàn/file nhạc, loa, nhạc cụ gõ, thiết bị số.\n- Học sinh: thanh phách, SGK Âm nhạc 1.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV cho HS hát lại bài Gà gáy, tạo không khí.","hs":"- HS hát tập thể."},{"ten":"2. Khám phá","gv":"- GV cùng HS nhắc lại nội dung, kĩ năng đã học ở chủ đề 6.","hs":"- HS nhắc lại kiến thức."},{"ten":"3. Luyện tập","gv":"- GV cho HS ôn hát kết hợp vận động, gõ đệm theo tốp ca, cả lớp.","hs":"- HS luyện tập nhiều hình thức."},{"ten":"4. Vận dụng — Sáng tạo","gv":"- GV khuyến khích HS sáng tạo động tác phụ họa; mời biểu diễn; củng cố chủ đề.","hs":"- HS sáng tạo, biểu diễn, trả lời củng cố."},{"ten":"5. Năng lực số & AI (tích hợp)","gv":"- (NLS mức 1) GV cho HS xem video biểu diễn dân ca thiếu nhi từ học liệu số để tham khảo phong cách.\n⚠ An toàn: HS quan sát; GV chọn video phù hợp lứa tuổi.","hs":"- HS xem học liệu số, học phong cách biểu diễn."}]},
{"lop":1,"mon":"Âm nhạc","tuan":27,"tiet":27,"bai":"Ôn tập giữa học kì II — Ôn các bài hát và nội dung chủ đề 5, 6","yccd":"1. Năng lực âm nhạc\n- Hát thuộc, đúng giai điệu các bài Xúc xắc xúc xẻ, Gà gáy.\n- Củng cố kĩ năng gõ đệm, vận động và đọc nhạc 5 nốt.\n2. Năng lực chung\n- Tự chủ và tự học: tự đánh giá kết quả học tập.\n3. Phẩm chất\n- Chăm chỉ, tự tin biểu diễn.","dodung":"- Giáo viên: đàn/file nhạc, loa, nhạc cụ gõ, thiết bị số.\n- Học sinh: thanh phách, SGK Âm nhạc 1.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV cho HS chơi Nghe giai điệu đoán tên bài hát đã học.","hs":"- HS lắng nghe, đoán tên bài."},{"ten":"2. Khám phá — Hệ thống lại","gv":"- GV cùng HS nhắc lại tên các bài hát, nội dung đã học ở chủ đề 5, 6.","hs":"- HS nhắc lại kiến thức."},{"ten":"3. Luyện tập","gv":"- GV cho HS ôn lần lượt từng bài hát kết hợp gõ đệm, vận động; ôn đọc nhạc.","hs":"- HS ôn hát, gõ đệm và đọc nhạc."},{"ten":"4. Vận dụng","gv":"- GV tổ chức cho các nhóm biểu diễn, nhận xét, tuyên dương.","hs":"- HS biểu diễn, nhận xét lẫn nhau."},{"ten":"5. Năng lực số & AI (tích hợp)","gv":"- (NLS mức 1) GV cho HS nghe lại các bản nhạc mẫu từ học liệu số để so sánh và tự chỉnh sửa.\n- (AI mức 1 — gợi ý) GV có thể dùng app hát karaoke thiếu nhi để HS ôn hát; GV thao tác và kiểm soát.\n⚠ An toàn: HS chỉ hát theo, không tự nhập liệu; nội dung do GV chọn.","hs":"- HS nghe/hát theo học liệu số, tự chỉnh sửa."}]},
{"lop":1,"mon":"Âm nhạc","tuan":28,"tiet":28,"bai":"Chủ đề 7: Gia đình — Học hát: Cây gia đình (Nhạc: Quỳnh Hợp, lời thơ: Nguyễn Thị Mai)","yccd":"1. Năng lực âm nhạc\n- Nhớ tên và hát rõ lời, đúng giai điệu bài Cây gia đình.\n- Cảm nhận tình cảm ấm áp, gắn bó giữa các thành viên trong gia đình qua bài hát.\n2. Năng lực chung\n- Giao tiếp và hợp tác: hát hòa giọng cùng bạn.\n3. Phẩm chất\n- Yêu gia đình, kính trọng ông bà, cha mẹ.","dodung":"- Giáo viên: đàn/file nhạc, loa, tranh gia đình, thanh phách, thiết bị số.\n- Học sinh: SGK Âm nhạc 1, thanh phách.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV cho HS xem tranh gia đình, hỏi trong nhà em có những ai, dẫn vào bài.","hs":"- HS quan sát, chia sẻ."},{"ten":"2. Khám phá — Học hát","gv":"- GV mở hát mẫu, đọc lời ca theo câu.\n- GV đàn và bắt nhịp cho HS tập hát từng câu đến hết bài.","hs":"- HS nghe mẫu, đọc lời, tập hát từng câu."},{"ten":"3. Luyện tập","gv":"- GV cho HS hát cả bài, sửa sai, kết hợp vỗ tay theo phách.","hs":"- HS hát cả bài, vỗ tay theo phách."},{"ten":"4. Vận dụng","gv":"- GV mời nhóm/cá nhân hát; dặn HS hát cho ông bà, bố mẹ nghe.","hs":"- HS biểu diễn, ghi nhớ nhiệm vụ."},{"ten":"5. Năng lực số & AI (tích hợp)","gv":"- (NLS mức 1) GV cho HS nghe bản hát mẫu chuẩn từ học liệu số để cảm thụ và hát theo.\n⚠ An toàn: HS chỉ nghe và hát theo; GV chọn học liệu phù hợp.","hs":"- HS nghe học liệu số, cảm thụ và hát theo."}]},
{"lop":1,"mon":"Âm nhạc","tuan":29,"tiet":29,"bai":"Chủ đề 7: Gia đình — Ôn bài hát Cây gia đình; Nghe nhạc: một bài hát về gia đình (Ru con)","yccd":"1. Năng lực âm nhạc\n- Hát thuộc, đúng giai điệu Cây gia đình, kết hợp vận động phụ họa.\n- Lắng nghe và cảm nhận tình cảm êm dịu của một bài hát/làn điệu về gia đình; biết vận động nhẹ nhàng.\n2. Năng lực chung\n- Tự chủ: mạnh dạn nêu cảm nhận.\n3. Phẩm chất\n- Yêu gia đình, biết ơn ông bà cha mẹ.","dodung":"- Giáo viên: đàn/file nhạc, loa, tranh gia đình, thanh phách, thiết bị số.\n- Học sinh: thanh phách, SGK Âm nhạc 1.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV cho HS hát lại bài Cây gia đình.","hs":"- HS hát tập thể."},{"ten":"2. Khám phá — Nghe nhạc","gv":"- GV mở một bài hát/làn điệu êm dịu về gia đình cho HS nghe; hỏi cảm nhận: êm dịu hay sôi động.","hs":"- HS lắng nghe, nêu cảm nhận."},{"ten":"3. Luyện tập","gv":"- GV cho HS ôn hát Cây gia đình kết hợp vận động phụ họa; nghe lại bài nghe nhạc và cảm thụ.","hs":"- HS ôn hát, vận động, cảm thụ."},{"ten":"4. Vận dụng","gv":"- GV mời nhóm biểu diễn, nhận xét, tuyên dương.","hs":"- HS biểu diễn, nhận xét."},{"ten":"5. Năng lực số & AI (tích hợp)","gv":"- (NLS mức 1) GV cho HS xem hình ảnh/video số ấm áp về gia đình kết hợp nghe nhạc để cảm thụ.\n⚠ An toàn: HS chỉ xem/nghe; GV chọn nội dung phù hợp.","hs":"- HS xem/nghe học liệu số, nêu cảm nhận."}]},
{"lop":1,"mon":"Âm nhạc","tuan":30,"tiet":30,"bai":"Chủ đề 7: Gia đình — Nhạc cụ: Gõ đệm theo bài hát; Vận động theo cặp","yccd":"1. Năng lực âm nhạc\n- Gõ đệm cho bài Cây gia đình bằng nhạc cụ gõ theo phách.\n- Biết hát kết hợp vận động phụ họa theo cặp/nhóm.\n2. Năng lực chung\n- Giao tiếp và hợp tác: phối hợp gõ đệm, biểu diễn cùng bạn.\n3. Phẩm chất\n- Yêu gia đình, đoàn kết, chăm chỉ.","dodung":"- Giáo viên: nhạc cụ gõ (thanh phách, trống con), đàn/file nhạc, loa, thiết bị số.\n- Học sinh: thanh phách, SGK Âm nhạc 1.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV cho HS hát lại bài Cây gia đình.","hs":"- HS hát tập thể."},{"ten":"2. Khám phá — Ôn cách gõ đệm","gv":"- GV làm mẫu gõ đệm theo phách cho bài hát; hướng dẫn HS.","hs":"- HS quan sát, làm theo."},{"ten":"3. Luyện tập — Gõ đệm","gv":"- GV cho HS gõ đệm cho bài Cây gia đình theo phách; kết hợp hát và vận động theo cặp.","hs":"- HS gõ đệm, hát và vận động theo cặp."},{"ten":"4. Vận dụng","gv":"- GV cho nhóm luân phiên biểu diễn vừa hát vừa gõ đệm, nhận xét.","hs":"- HS nhóm biểu diễn, nhận xét lẫn nhau."},{"ten":"5. Năng lực số & AI (tích hợp)","gv":"- (NLS mức 1) GV mở nhạc đệm chuẩn từ thiết bị số để HS giữ nhịp ổn định khi gõ đệm.\n⚠ An toàn: GV thao tác và kiểm soát thiết bị.","hs":"- HS gõ đệm theo nhạc đệm số, giữ nhịp."}]},
{"lop":1,"mon":"Âm nhạc","tuan":31,"tiet":31,"bai":"Chủ đề 7: Gia đình — Vận dụng — Sáng tạo; Ôn tập chủ đề 7","yccd":"1. Năng lực âm nhạc\n- Hát thuộc và biểu diễn bài Cây gia đình kết hợp vận động, gõ đệm.\n- Củng cố cảm nhận tình cảm gia đình qua âm nhạc.\n2. Năng lực chung\n- Giải quyết vấn đề và sáng tạo: nghĩ động tác phụ họa.\n3. Phẩm chất\n- Yêu gia đình, tự tin thể hiện.","dodung":"- Giáo viên: đàn/file nhạc, loa, nhạc cụ gõ, thiết bị số.\n- Học sinh: thanh phách, SGK Âm nhạc 1.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV cho HS chơi trò chơi thể hiện các thành viên gia đình bằng động tác.","hs":"- HS tham gia trò chơi."},{"ten":"2. Khám phá","gv":"- GV cùng HS nhắc lại nội dung, cảm xúc đã học ở chủ đề 7.","hs":"- HS nhắc lại kiến thức."},{"ten":"3. Luyện tập","gv":"- GV cho HS ôn hát kết hợp vận động, gõ đệm theo tốp ca, cả lớp.","hs":"- HS luyện tập nhiều hình thức."},{"ten":"4. Vận dụng — Sáng tạo","gv":"- GV khuyến khích HS sáng tạo động tác phụ họa; mời biểu diễn; củng cố chủ đề.","hs":"- HS sáng tạo, biểu diễn, trả lời củng cố."},{"ten":"5. Năng lực số & AI (tích hợp)","gv":"- (NLS mức 1) GV cho HS nghe lại bản nhạc mẫu từ học liệu số để tự chỉnh sửa khi biểu diễn.\n⚠ An toàn: GV kiểm soát thiết bị và học liệu.","hs":"- HS nghe học liệu số, chỉnh sửa biểu diễn."}]},
{"lop":1,"mon":"Âm nhạc","tuan":32,"tiet":32,"bai":"Chủ đề 8: Vui đón hè — Học hát: Ngôi sao lấp lánh (Nhạc nước ngoài; sưu tầm, biên soạn: Thanh Vân)","yccd":"1. Năng lực âm nhạc\n- Nhớ tên và hát rõ lời, đúng giai điệu bài Ngôi sao lấp lánh.\n- Cảm nhận tính chất nhẹ nhàng, trong sáng của bài hát.\n2. Năng lực chung\n- Giao tiếp và hợp tác: hát hòa giọng cùng bạn.\n3. Phẩm chất\n- Yêu thiên nhiên, yêu bầu trời đêm mùa hè.","dodung":"- Giáo viên: đàn/file nhạc, loa, tranh bầu trời sao mùa hè, thanh phách, thiết bị số.\n- Học sinh: SGK Âm nhạc 1, thanh phách.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV cho HS xem tranh bầu trời đêm đầy sao, hỏi các em thấy gì, dẫn vào bài.","hs":"- HS quan sát, trả lời."},{"ten":"2. Khám phá — Học hát","gv":"- GV mở hát mẫu, đọc lời ca theo câu.\n- GV đàn và bắt nhịp cho HS tập hát từng câu đến hết bài.","hs":"- HS nghe mẫu, đọc lời, tập hát từng câu."},{"ten":"3. Luyện tập","gv":"- GV cho HS hát cả bài, sửa sai, kết hợp vỗ tay theo phách.","hs":"- HS hát cả bài, vỗ tay theo phách."},{"ten":"4. Vận dụng","gv":"- GV mời nhóm/cá nhân hát; dặn HS hát cho gia đình nghe.","hs":"- HS biểu diễn, ghi nhớ nhiệm vụ."},{"ten":"5. Năng lực số & AI (tích hợp)","gv":"- (NLS mức 1) GV cho HS nghe bản hát mẫu chuẩn và xem hình ảnh bầu trời sao từ học liệu số để tăng cảm xúc.\n⚠ An toàn: HS chỉ nghe/xem; GV chọn học liệu phù hợp.","hs":"- HS nghe/xem học liệu số, cảm thụ và hát theo."}]},
{"lop":1,"mon":"Âm nhạc","tuan":33,"tiet":33,"bai":"Chủ đề 8: Vui đón hè — Ôn bài hát Ngôi sao lấp lánh; Nhạc cụ: Trai-en-gô (Triangle)","yccd":"1. Năng lực âm nhạc\n- Hát thuộc, đúng giai điệu Ngôi sao lấp lánh, thể hiện sắc thái to — nhỏ.\n- Nhận biết, gọi tên nhạc cụ trai-en-gô; biết cách gõ và gõ đệm theo bài hát.\n2. Năng lực chung\n- Tự chủ và tự học: tự luyện tập gõ đệm.\n3. Phẩm chất\n- Chăm chỉ luyện tập nhạc cụ.","dodung":"- Giáo viên: nhạc cụ trai-en-gô (hoặc thay thế), đàn/file nhạc, loa, tranh nhạc cụ, thiết bị số.\n- Học sinh: thanh phách, SGK Âm nhạc 1.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV cho HS hát lại bài Ngôi sao lấp lánh.","hs":"- HS hát tập thể."},{"ten":"2. Khám phá — Giới thiệu trai-en-gô","gv":"- GV cho HS xem nhạc cụ thật, giới thiệu hình dáng, âm sắc trong trẻo của trai-en-gô; làm mẫu cách cầm và gõ.","hs":"- HS quan sát, nghe âm thanh, xem mẫu."},{"ten":"3. Luyện tập — Gõ đệm","gv":"- GV cho HS thực hành gõ trai-en-gô; gõ đệm cho bài hát; sửa sai.","hs":"- HS thực hành gõ và gõ đệm theo bài hát."},{"ten":"4. Vận dụng","gv":"- GV cho nhóm luân phiên hát và gõ đệm.","hs":"- HS nhóm hát và gõ đệm, nhận xét lẫn nhau."},{"ten":"5. Năng lực số & AI (tích hợp)","gv":"- (NLS mức 1) GV cho HS nghe âm thanh mẫu trai-en-gô qua học liệu số để phân biệt âm sắc.\n⚠ An toàn: HS nghe và làm theo; GV chọn nguồn học liệu.","hs":"- HS nghe âm thanh số, so sánh với gõ thực tế."}]},
{"lop":1,"mon":"Âm nhạc","tuan":34,"tiet":34,"bai":"Chủ đề 8: Vui đón hè — Đọc nhạc: Hát cùng Đô — Rê — Mi — Pha — Son; Vận dụng — Sáng tạo","yccd":"1. Năng lực âm nhạc\n- Đọc đúng cao độ 5 nốt Đô — Rê — Mi — Pha — Son theo kí hiệu bàn tay, thể hiện sắc thái to — nhỏ.\n- Biểu diễn bài Ngôi sao lấp lánh kết hợp vận động, gõ đệm.\n2. Năng lực chung\n- Giải quyết vấn đề và sáng tạo: nghĩ động tác phụ họa.\n3. Phẩm chất\n- Yêu âm nhạc, tự tin thể hiện.","dodung":"- Giáo viên: đàn/file nhạc, loa, tranh kí hiệu bàn tay, nhạc cụ gõ, thiết bị số.\n- Học sinh: thanh phách, SGK Âm nhạc 1.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV cho HS ôn lại cao độ 5 nốt qua kí hiệu bàn tay.","hs":"- HS đọc và làm kí hiệu bàn tay."},{"ten":"2. Khám phá — Đọc nhạc","gv":"- GV đọc mẫu bài Hát cùng Đô-Rê-Mi-Pha-Son, thể hiện to — nhỏ; hướng dẫn HS đọc theo.","hs":"- HS nghe mẫu, đọc theo và làm kí hiệu."},{"ten":"3. Luyện tập","gv":"- GV cho HS đọc cả bài kết hợp gõ đệm; ôn hát Ngôi sao lấp lánh kết hợp vận động.","hs":"- HS đọc nhạc, gõ đệm; ôn hát và vận động."},{"ten":"4. Vận dụng — Sáng tạo","gv":"- GV khuyến khích HS sáng tạo động tác phụ họa; mời biểu diễn; củng cố chủ đề.","hs":"- HS sáng tạo, biểu diễn, trả lời củng cố."},{"ten":"5. Năng lực số & AI (tích hợp)","gv":"- (NLS mức 1) GV cho HS nghe cao độ mẫu 5 nốt qua học liệu số/đàn phím ảo để đọc cho đúng.\n⚠ An toàn: HS nghe và đọc theo; GV thao tác và kiểm soát thiết bị.","hs":"- HS nghe cao độ mẫu số, đọc theo cho chuẩn."}]},
{"lop":1,"mon":"Âm nhạc","tuan":35,"tiet":35,"bai":"Ôn tập và đánh giá cuối năm học","yccd":"1. Năng lực âm nhạc\n- Hát thuộc, đúng giai điệu các bài hát đã học trong năm; biết gõ đệm và vận động phù hợp.\n- Nhận biết các nhạc cụ gõ đã học (thanh phách, trống con, trai-en-gô) và đọc được 5 nốt Đô-Rê-Mi-Pha-Son.\n2. Năng lực chung\n- Tự chủ và tự học: tự đánh giá kết quả học tập cả năm.\n3. Phẩm chất\n- Chăm chỉ, tự tin biểu diễn.","dodung":"- Giáo viên: đàn/file nhạc, loa, nhạc cụ gõ, phiếu đánh giá, thiết bị số.\n- Học sinh: thanh phách, SGK Âm nhạc 1.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV cho HS chơi Nghe giai điệu đoán tên bài hát đã học trong năm.","hs":"- HS lắng nghe, đoán tên bài."},{"ten":"2. Khám phá — Hệ thống","gv":"- GV cùng HS hệ thống lại các bài hát, nhạc cụ, nội dung đọc nhạc đã học cả năm.","hs":"- HS nhắc lại kiến thức."},{"ten":"3. Luyện tập — Đánh giá","gv":"- GV cho từng nhóm/cá nhân biểu diễn một bài tự chọn; GV nhận xét, đánh giá theo sự tiến bộ.","hs":"- HS biểu diễn, tự nhận xét và nhận xét bạn."},{"ten":"4. Vận dụng","gv":"- GV tổ chức buổi biểu diễn nhỏ tổng kết năm học; tuyên dương, động viên HS; dặn dò HS giữ tình yêu âm nhạc trong dịp hè.","hs":"- HS tham gia biểu diễn, cổ vũ bạn, ghi nhớ."},{"ten":"5. Năng lực số & AI (tích hợp)","gv":"- (NLS mức 1) GV cho HS nghe lại các bản nhạc mẫu từ học liệu số để ôn tập và tự đánh giá.\n- (AI mức 1 — gợi ý) GV có thể dùng app hát karaoke thiếu nhi cho phần biểu diễn tổng kết; GV thao tác và kiểm soát.\n⚠ An toàn: HS chỉ hát/biểu diễn theo, không tự thao tác thiết bị; nội dung do GV chọn.","hs":"- HS nghe/hát theo học liệu số trong phần biểu diễn."}]}
];
